  weeklyNewCount: number;
  interviewCount: number;
  notifiedCount: number;
  unnotifiedCount: number;
  hiredCount: number;
  hiredNames: string[];
  totalActivePool: number;
  baselineTotal: number;
  baselineUnnotified: number;
  baselineNotified: number;
  baselineAccepted: number;
  baselineDeclined: number;
  baselineNoanswer: number;
